INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3003, 'es-ES', '<h2>Privacy Policy</h2><p>Thank you for using this application. We valor and protect your personal information and process it only as necessary to provide account login, application features, and customer service.</p><h3>I. Use of Information</h3><p>We use your information in accordance with applicable laws and this policy, and will Sin use it for unrelated purposes.</p><h3>II. Your Rights</h3><p>You may access, correct, or Eliminar your personal information in accordance with the law, or contact us through the channels published in the application.</p>');
INSERT IGNORE INTO `base_translation` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3004, 'es-ES', '<h2>Terms of Service</h2><p>Welcome to this application. Por favor read and understand this agreement and the related rules before using the application. By using the application services, you agree to comply with them.</p><h3>I. Service Use</h3><p>Por favor use each feature lawfully and in accordance with the instructions on the página. You must Sin use this application for illegal activities or activities that infringe on the rights of others.</p><h3>II. Changes to the Agreement</h3><p>We may update this agreement according to changes in business and laws and regulations, and will display the updated version in the application.</p>');
